import codecs, json, sys, unicodedata
assert sys.version_info[:3] == (3, 14, 7)
assert unicodedata.unidata_version == '16.0.0'
def failure(e):
    args = list(e.args)
    if isinstance(e, (UnicodeDecodeError, UnicodeEncodeError)):
        args[1] = list(e.object) if isinstance(e.object, bytes) else list(map(ord, e.object))
    return ['error', type(e).__name__, str(e), args]
def packed(data, flags=0):
    return int.from_bytes(bytes([len(data)]) + data + flags.to_bytes(8, 'little'), 'little')
rows = []
encoder_states = [-1, 0, 1, 8, 9, 255, 1 << 136, (1 << 136) - 1]
encoder_states += [packed(data, flags) for data in (b'', b'A', b'ABCDEFGH', b'\xff', b'\xc2', b'\xc2A', b'\xed\xa0\x80', '中'.encode(), '🐍'.encode()) for flags in (0, (1 << 64) - 1)]
encoder_states += [packed(b'Z', 42) | (1 << 135)]
for name in ('big5', 'cp950'):
    for state in encoder_states:
        encoder = codecs.getincrementalencoder(name)()
        encoder.setstate(packed(b'Z', 99))
        try:
            encoder.setstate(state)
            result = ['ok']
        except Exception as e:
            result = failure(e)
        saved = str(encoder.getstate())
        steps = []
        for errors, text, final in (('strict', 'A中', False), ('replace', '🐍', True)):
            encoder.errors = errors
            try: step = ['ok', list(encoder.encode(text, final))]
            except Exception as e: step = failure(e)
            steps.append([step, str(encoder.getstate())])
        encoder.reset()
        rows.append(dict(name=name, operation='encode', state=str(state), result=result, saved=saved, steps=steps, reset=str(encoder.getstate())))
    for pending in (b'', b'\xa4', b'\xff', b'ABC\xa4', b'ABCDEFGH', b'ABCDEFGHI'):
        for flags in (-1, 0, (1 << 64) - 1, 1 << 64):
            for final in (False, True):
                decoder = codecs.getincrementaldecoder(name)()
                decoder.setstate((b'Z', 99))
                try:
                    decoder.setstate((pending, flags))
                    result = ['ok']
                except Exception as e: result = failure(e)
                def decoder_state():
                    data, value = decoder.getstate()
                    return [list(data), str(value)]
                saved = decoder_state()
                steps = []
                for errors, data, flush in (('strict', b'\xa4A', final), ('replace', b'\xff', True)):
                    decoder.errors = errors
                    try: step = ['ok', list(map(ord, decoder.decode(data, flush)))]
                    except Exception as e: step = failure(e)
                    steps.append([step, decoder_state()])
                decoder.reset()
                rows.append(dict(name=name, operation='decode', pending=list(pending), state=str(flags), final=final, result=result, saved=saved, steps=steps, reset=decoder_state()))
print(json.dumps(dict(oracle=dict(version=sys.version, unicode=unicodedata.unidata_version, platform=sys.platform, byteorder=sys.byteorder), cases=rows)))
